from pyteal import *

def approval_program():
    fee_limit = Int(2000)
    asset_id = Int(654321)
    asset_receiver = Addr("QZYC3VHRXWYHNFU5OQZCO5OGV6Y5BQ3U6NBCOJPG5CE3KKLJC3QFNKBJW4")
    amount = Int(100)

    def check_payment(idx, recv, amt):
        return And(
            Gtxn[idx].type_enum() == TxnType.Payment,
            Gtxn[idx].receiver() == recv,
            Gtxn[idx].fee() <= fee_limit,
            Gtxn[idx].close_remainder_to() == Global.zero_address(),
            Gtxn[idx].rekey_to() == Global.zero_address(),
        )

    def validate_asset_transfer(idx, aid, recv, amt):
        return And(
            Gtxn[idx].type_enum() == TxnType.AssetTransfer,
            Gtxn[idx].xfer_asset() == aid,
            Gtxn[idx].asset_receiver() == recv,
            Gtxn[idx].asset_close_to() == Global.zero_address(),
            Gtxn[idx].rekey_to() == Global.zero_address(),
        )

    def check_opt_in(idx, aid):
        return And(
            Gtxn[idx].type_enum() == TxnType.AssetTransfer,
            Gtxn[idx].xfer_asset() == aid,
            Gtxn[idx].asset_receiver() == Gtxn[idx].sender(),
            Gtxn[idx].asset_amount() == Int(0),
            Gtxn[idx].fee() <= fee_limit,
            Gtxn[idx].asset_close_to()== Global.zero_address(),
            Gtxn[idx].rekey_to() == Global.zero_address(),
        )

    txn_2 = validate_asset_transfer(2, asset_id, asset_receiver, amount)
    txn_3 = check_opt_in(3, asset_id)

    return And(
        Global.group_size() == Int(4),
        check_payment(0, Addr("EAF7N2GQPDCON7I5QVJXMFSSTV4J2OY66TOAYPHNGS7W76PCSUHU2RIMSY"), 2000000),
        check_payment(1, Addr("JLFZ7MYYQOZQQIKISR7X7H4AF6J6TDFPJXH4YCNDOHKIFOODABYX7PEYXM"), 1000000),
        txn_2,
        txn_3
    )

def clear_program():
    return Approve()

if __name__ == "__main__":
    print(compileTeal(approval_program(), mode=Mode.Signature, version=5))
